   SET SPEC_CODE = #{specCode,jdbcType=VARCHAR},
       EMBRYO_CODE = #{embryoCode,jdbcType=VARCHAR}
 WHERE ifnull(IS_DELETE, 0) = 0
   AND FACTORY_CODE = #{plan.factoryCode,jdbcType=VARCHAR}
   AND YEAR = #{plan.year,jdbcType=DECIMAL}
   AND MONTH = #{plan.month,jdbcType=DECIMAL}
   AND MONTH_PLAN_VERSION = #{plan.monthPlanVersion,jdbcType=VARCHAR}
   AND PRODUCTION_VERSION = #{plan.productionVersion,jdbcType=VARCHAR}
   AND PRODUCT_CODE = #{plan.productCode,jdbcType=VARCHAR}
   AND BRAND = #{plan.brand,jdbcType=VARCHAR}

   AND CHANNEL = #{plan.channel,jdbcType=VARCHAR}


   AND CHANNEL IS NULL

   AND LOCATION_TYPE = #{plan.locationType,jdbcType=VARCHAR}
   AND SPEC_CODE = #{plan.specCode,jdbcType=VARCHAR}

   AND DELIVERY_DATE_DUE IS NOT NULL


